def _in_window(self, key, now):
    q = self._accepted.setdefault(key, __import__("collections").deque())
    bucket_start = (now // self.window) * self.window
    while q and q[0] < bucket_start:
        q.popleft()
    return q

def allow(self, key, now):
    self._observe(now)
    q = self._in_window(key, now)
    if len(q) < self.limit:
        q.append(now)
        return True
    return False

def remaining(self, key, now):
    self._observe(now)
    q = self._in_window(key, now)
    return max(self.limit - len(q), 0)

def retry_after(self, key, now):
    self._observe(now)
    if self.limit == 0:
        return math.inf
    q = self._in_window(key, now)
    if len(q) < self.limit:
        return 0.0
    return float(q[0] + self.window - now)
